 std: ['S239', 'S242', 'S247', 'S4729', 'S4730', 'S4733'],
 method: { goals: ['Žiak zostaví potravový reťazec z organizmov lesa.', 'Žiak rozlíši výrobcu, spotrebiteľa a rozkladača.', 'Žiak vysvetlí, čo sa stane, keď jeden článok reťazca chýba.'],
  plan: [['5 min', 'Otázka: Kto v lese čo je?'], ['15 min', 'Odkrývanie kruhu a pomenovanie článkov.'], ['15 min', 'Skupiny skladajú reťazce z kartičiek organizmov.'], ['10 min', 'Diskusia: čo ak zmiznú myši?']],
  ask: ['Prečo potrebuje sova rastliny, aj keď ich neje?', 'Čo by sa stalo s lesom bez rozkladačov?'] },
 guide: { primer: 'Potravový reťazec ukazuje, kto koho je. Na začiatku sú vždy zelené rastliny, ktoré si potravu vyrobia samy pomocou slnka. Nasledujú bylinožravce a mäsožravce. Odumreté telá a lístie rozložia huby, baktérie a dážďovky na látky, ktoré opäť prijmú rastliny.',
  steps: [
   { time: '5 min', do: 'Napíšte na tabuľu: žaluď, myš, sova. Spýtajte sa, ako spolu súvisia.', say: 'Kto z nich koho je? Kto by bez koho neprežil?', check: 'Žiaci nájdu správne poradie.' },
   { time: '15 min', do: 'Odkrývajte kruh. Pri rozkladačoch sa zastavte, na tie žiaci zabúdajú.', say: 'Čo sa stane s listami, ktoré na jeseň spadnú na zem?', check: 'Žiaci vysvetlia, prečo sa kruh uzatvára.' },
   { time: '15 min', do: 'Skupiny dostanú kartičky lesných organizmov a poskladajú z nich čo najviac reťazcov.', check: 'Každý reťazec začína rastlinou.' },
   { time: '10 min', do: 'Diskusia s rybou: čo spôsobí, keď zmizne jeden článok.', check: 'Žiaci uvedú dôsledok pre ďalší článok.' }],
  traps: [['Reťazec môže začať zvieraťom.', 'Každý reťazec začína zelenou rastlinou, ktorá si potravu vyrobí sama.'], ['Šípka ukazuje, kto koho uloví.', 'Šípka ukazuje, kam ide potrava a energia: od toho, kto je zjedený, k tomu, kto ho zje.'], ['Rozkladače nie sú dôležité.', 'Bez nich by les zasypalo lístie a rastliny by nemali živiny.']],
  qa: [['Je medveď mäsožravec?', 'Medveď hnedý je všežravec. Je bobule, korienky, hmyz aj mäso.'], ['Je človek tiež v potravovom reťazci?', 'Áno, človek je spotrebiteľ, je rastliny aj živočíchy.']] },
