 id: 'fotosynteza', title: 'Fotosyntéza', aka: ['Výživa rastlín', 'Ako sa rastlina živí'], subject: 'Biológia', grade: 8, kind: 'proces', rec: 'cycle',
 why: 'Fotosyntéza a dýchanie si odovzdávajú kyslík a oxid uhličitý dokola. Kruh ukáže, čo rastlina prijíma, čo vyrába a kam to ide.',
 alts: [['ttable', 'Keď porovnávate fotosyntézu a dýchanie.'], ['mind', 'Keď zhŕňate podmienky a produkty.'], ['scene', 'Keď chcete ukázať prúdenie látok cez list.']],
 std: ['S512', 'S513', 'S4878'],
 method: { goals: ['Žiak vymenuje látky, ktoré rastlina pri fotosyntéze prijíma a vytvára.', 'Žiak vysvetlí úlohu svetla a chlorofylu.', 'Žiak porovná fotosyntézu s dýchaním.'],
  plan: [['5 min', 'Otázka: Odkiaľ berie strom hmotu na svoj kmeň?'], ['15 min', 'Odkrývanie kruhu fotosyntézy.'], ['15 min', 'Porovnávacia tabuľka fotosyntéza a dýchanie.'], ['10 min', 'Kvíz a jednoduchý pokus s vodnou rastlinou.']],
  ask: ['Prečo rastlina v tme nerastie?', 'Prečo potrebujeme lesy na dýchanie?'] },
 guide: { primer: 'Pri fotosyntéze rastlina vyrába cukor (glukózu) z oxidu uhličitého a vody. Energiu dodáva svetlo, ktoré zachytí zelené farbivo chlorofyl v chloroplastoch. Vedľajším produktom je kyslík, ktorý rastlina uvoľní do vzduchu. Rastlina zároveň stále dýcha, rovnako ako živočíchy.',
  steps: [
   { time: '5 min', do: 'Položte provokatívnu otázku o strome.', say: 'Veľký strom váži tony. Odkiaľ sa vzala všetka tá hmota? Zo zeme?', check: 'Väčšina žiakov tipne pôdu. Vráťte sa k tomu na konci.' },
   { time: '15 min', do: 'Odkrývajte kruh: svetlo, oxid uhličitý, voda, cukor, kyslík.', say: 'Čo z toho rastlina berie zo vzduchu a čo zo zeme?', check: 'Žiaci zaradia oxid uhličitý ako vstup zo vzduchu.' },
   { time: '15 min', do: 'Žiaci vyplnia tabuľku fotosyntéza a dýchanie.', check: 'Sledujte, či nepíšu, že rastliny nedýchajú.' },
   { time: '10 min', do: 'Ukážte bublinky kyslíka pri vodnej rastline na svetle alebo video a urobte kvíz.', check: 'Žiaci vysvetlia, odkiaľ sú bublinky.' }],
  traps: [['Rastliny nedýchajú, len robia fotosyntézu.', 'Rastliny dýchajú stále, cez deň aj v noci. Fotosyntéza prebieha len na svetle.'], ['Hmota stromu pochádza z pôdy.', 'Väčšina hmoty vzniká z oxidu uhličitého zo vzduchu a z vody.'], ['Kyslík vzniká z oxidu uhličitého.', 'Kyslík pri fotosyntéze pochádza z rozkladu vody.']],
  qa: [['Prečo sú listy na jeseň žlté?', 'Chlorofyl sa rozkladá a ukážu sa žlté a oranžové farbivá, ktoré v liste boli aj predtým.'], ['Robia fotosyntézu aj riasy?', 'Áno, a v moriach vyrábajú veľkú časť kyslíka na Zemi.']] },
