  plan: [['5 min', 'Otázka: Ako dlho trvá, kým potrava prejde telom?'], ['15 min', 'Odkrývanie cesty potravy na tabuli.'], ['15 min', 'Žiaci priradia úlohy k orgánom na obrázku tela.'], ['10 min', 'Kvíz a pravidlá zdravého jedenia.']],
