  steps: [
   { time: '5 min', do: 'Spýtajte sa, čo sa stane so sendvičom po prehltnutí.', say: 'Zjedli ste desiatu. Kam presne putuje a čo sa s ňou deje?', check: 'Zapíšte, ktoré orgány žiaci poznajú.' },
   { time: '15 min', do: 'Odkrývajte kroky od úst po konečník. Pri tenkom čreve zdôraznite vstrebávanie.', say: 'Kde podľa vás prechádzajú živiny z potravy do krvi?', check: 'Žiaci správne umiestnia tenké črevo.' },
   { time: '15 min', do: 'Žiaci na obrys tela zakreslia orgány a ku každému napíšu úlohu.', check: 'Sledujte, či nezamieňajú tenké a hrubé črevo.' },
   { time: '10 min', do: 'Kvíz a spoločné pravidlá zdravého stravovania.', check: 'Každý žiak vysvetlí jeden orgán vlastnými slovami.' }],
